-- BEGIN HISTORICAL MIGRATION: 20260729000004_add_audit_logs_self_select.sql
--
-- Allow users to SELECT their own audit_logs entries
--
-- By default, audit_logs is admin-only (for both SELECT and INSERT).
-- This policy lets general users see entries where they are the target,
-- giving them visibility into admin actions that affect their account
-- (e.g., role upgrades, moderation actions).
--
-- Security: users can only see rows where target_profile_id = auth.uid(),
-- and cannot modify audit_logs in any way.

DROP POLICY IF EXISTS audit_logs_self_select ON audit_logs;
CREATE POLICY audit_logs_self_select ON audit_logs
  FOR SELECT TO authenticated
  USING (
    target_profile_id = auth.uid()
  );

-- Note: The existing audit_logs_admin_read policy remains in place
-- for admin users who can see ALL audit logs.
-- The system_insert policy also remains for service_role writes.

-- END HISTORICAL MIGRATION: 20260729000004_add_audit_logs_self_select.sql

--
-- BEGIN HISTORICAL MIGRATION: 20260803000001_add_category_forms_recurrence.sql
--
-- Migration: Add category, registration_form_config, recurrence_rule, series_id to events
-- Create event_registration_responses table with RLS isolation
-- Date: 2026-08-03

-- 1. Add new columns to events table
ALTER TABLE events
  ADD COLUMN IF NOT EXISTS category TEXT NOT NULL DEFAULT 'Social'
    CHECK (category IN ('Social', 'Practice')),
  ADD COLUMN IF NOT EXISTS registration_form_config JSONB DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS recurrence_rule JSONB DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS series_id UUID DEFAULT NULL;

-- 2. Create event_registration_responses table for RLS-isolated form responses
CREATE TABLE IF NOT EXISTS event_registration_responses (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  registration_id UUID NOT NULL REFERENCES event_registrations(id) ON DELETE CASCADE,
  responses JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT TIMEZONE('utc', NOW()),
  UNIQUE (registration_id)
);

-- 3. Enable RLS on new table
ALTER TABLE event_registration_responses ENABLE ROW LEVEL SECURITY;

-- 4. RLS for event_registration_responses:
--    SELECT: only the registrant, event host, or admin
CREATE POLICY reg_responses_read_self_host_admin ON event_registration_responses FOR SELECT TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM event_registrations er
    WHERE er.id = registration_id
      AND (
        er.profile_id = auth.uid()
        OR EXISTS (
          SELECT 1 FROM events e
          WHERE e.id = er.event_id AND e.creator_id = auth.uid()
        )
      )
  )
  OR auth.jwt() ->> 'role' = 'admin'
);

--    INSERT: only via service role (Edge Functions bypass RLS)
CREATE POLICY reg_responses_service_insert ON event_registration_responses FOR INSERT TO authenticated
WITH CHECK (auth.jwt() ->> 'role' = 'service_role');

--    UPDATE: only via service role
CREATE POLICY reg_responses_service_update ON event_registration_responses FOR UPDATE TO authenticated
USING (auth.jwt() ->> 'role' = 'service_role')
WITH CHECK (auth.jwt() ->> 'role' = 'service_role');

-- 5. New indexes for category filtering and series lookups
CREATE INDEX IF NOT EXISTS idx_events_category ON events (category);
CREATE INDEX IF NOT EXISTS idx_events_series_id ON events (series_id) WHERE series_id IS NOT NULL;

-- END HISTORICAL MIGRATION: 20260803000001_add_category_forms_recurrence.sql

--
-- BEGIN HISTORICAL MIGRATION: 20260805000001_add_registration_checkin.sql
--
-- Migration: 20260805000001_add_registration_checkin.sql
-- 1. 為 event_registrations 新增 checked_in_at 欄位，記錄實際出席簽到時間
-- 2. 新增 waitlist_converted_at 欄位，記錄候補轉化時間（供 get-user-analytics 統計）
-- 3. 更新 promote_waitlist_on_cancel trigger 以設定 waitlist_converted_at
-- 4. 新增主辦人簽到 RLS 政策

-- ============================================================
-- Step 1: Add checked_in_at column
-- ============================================================
ALTER TABLE event_registrations
ADD COLUMN IF NOT EXISTS checked_in_at TIMESTAMPTZ;

COMMENT ON COLUMN event_registrations.checked_in_at IS '實際出席簽到時間戳，NULL 表示尚未簽到。僅 status = approved 的報名可被簽到。';

-- ============================================================
-- Step 2: Add waitlist_converted_at column
-- ============================================================
-- 供 get-user-analytics 統計「候補轉化數」使用。
-- 當候補者被自動遞補為 pending 時，由 trigger 填入時間戳。
ALTER TABLE event_registrations
ADD COLUMN IF NOT EXISTS waitlist_converted_at TIMESTAMPTZ;

COMMENT ON COLUMN event_registrations.waitlist_converted_at IS '候補轉化時間戳。當 waitlisted 記錄被 promote 為 pending 時，由 trigger 填入。NULL 表示未曾從候補轉化。';

-- ============================================================
-- Step 3: Update promote trigger to set waitlist_converted_at
-- ============================================================
CREATE OR REPLACE FUNCTION promote_waitlist_on_cancel()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  next_waitlist RECORD;
  current_approved_count INT;
  event_max_cap INT;
BEGIN
  IF OLD.status NOT IN ('approved', 'waitlisted') OR NEW.status != 'cancelled' THEN
    RETURN NEW;
  END IF;

  SELECT max_capacity INTO event_max_cap
  FROM events WHERE id = OLD.event_id;

  SELECT COUNT(*) INTO current_approved_count
  FROM event_registrations
  WHERE event_id = OLD.event_id AND status = 'approved';

  SELECT * INTO next_waitlist
  FROM event_registrations
  WHERE event_id = OLD.event_id
    AND status = 'waitlisted'
  ORDER BY created_at ASC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF event_max_cap IS NOT NULL AND current_approved_count >= event_max_cap THEN
    RETURN NEW;
  END IF;

  UPDATE event_registrations
  SET status = 'pending',
      waitlist_position = NULL,
      waitlist_converted_at = TIMEZONE('utc', NOW())
  WHERE id = next_waitlist.id;

  RETURN NEW;
END;
$$;

-- ============================================================
-- Step 4: Add explicit check-in RLS policy for event hosts
-- ============================================================
CREATE POLICY registrations_checkin_host
  ON event_registrations
  FOR UPDATE TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM events e
      WHERE e.id = event_id AND e.creator_id = auth.uid()
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM events e
      WHERE e.id = event_id AND e.creator_id = auth.uid()
    )
  );

-- END HISTORICAL MIGRATION: 20260805000001_add_registration_checkin.sql

