-- BEGIN HISTORICAL MIGRATION: 20260810000001_restrict_draft_event_visibility.sql
--
-- Draft events are private to their creator regardless of visibility_settings.
DROP POLICY IF EXISTS events_read_visibility ON events;

CREATE POLICY events_read_visibility ON events FOR SELECT TO authenticated
USING (
  creator_id = auth.uid()
  OR (
    lifecycle_status <> 'draft'
    AND (
      (visibility_settings ->> 'type') IS NULL
      OR (visibility_settings ->> 'type') = 'public'
      OR (
        (visibility_settings ->> 'type') = 'connections_only'
        AND EXISTS (
          SELECT 1 FROM connections c
          WHERE c.status = 'accepted'
            AND (
              (c.requester_id = auth.uid() AND c.receiver_id = events.creator_id)
              OR
              (c.requester_id = events.creator_id AND c.receiver_id = auth.uid())
            )
        )
      )
    )
  )
);

-- END HISTORICAL MIGRATION: 20260810000001_restrict_draft_event_visibility.sql

--
-- BEGIN HISTORICAL MIGRATION: 20260810000002_add_event_publication_control.sql
--
-- Event publication control is separate from lifecycle_status.
-- The initial events table predates lifecycle_status. Preserve existing events
-- as published, then make newly created events drafts by default.
ALTER TABLE public.events
  ADD COLUMN IF NOT EXISTS lifecycle_status TEXT NOT NULL DEFAULT 'published';

ALTER TABLE public.events
  DROP CONSTRAINT IF EXISTS events_lifecycle_status_check,
  ADD CONSTRAINT events_lifecycle_status_check
    CHECK (lifecycle_status IN (
      'draft',
      'published',
      'registration_open',
      'registration_closed',
      'completed',
      'archived',
      'cancelled'
    ));

ALTER TABLE public.events
  ALTER COLUMN lifecycle_status SET DEFAULT 'draft';

ALTER TABLE public.events
  ADD COLUMN IF NOT EXISTS publication_status TEXT NOT NULL DEFAULT 'closed',
  ADD COLUMN IF NOT EXISTS publish_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS unpublish_at TIMESTAMPTZ;

UPDATE public.events
SET publication_status = CASE
  WHEN lifecycle_status = 'draft' THEN 'closed'
  ELSE 'published'
END
WHERE publication_status = 'closed';

ALTER TABLE public.events
  DROP CONSTRAINT IF EXISTS events_publication_status_check,
  ADD CONSTRAINT events_publication_status_check
    CHECK (publication_status IN ('published', 'closed')),
  DROP CONSTRAINT IF EXISTS events_publication_schedule_order,
  ADD CONSTRAINT events_publication_schedule_order
    CHECK (publish_at IS NULL OR unpublish_at IS NULL OR publish_at < unpublish_at);

CREATE INDEX IF NOT EXISTS idx_events_publication_schedule
  ON public.events (publication_status, publish_at, unpublish_at);

CREATE OR REPLACE FUNCTION public.prevent_direct_event_publication_update()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF (OLD.publication_status, OLD.publish_at, OLD.unpublish_at)
     IS DISTINCT FROM (NEW.publication_status, NEW.publish_at, NEW.unpublish_at)
    AND COALESCE(current_setting('app.event_publication_rpc', true), '') <> 'on'
  THEN
    RAISE EXCEPTION 'event publication must be changed through set_event_publication';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_prevent_direct_event_publication_update ON public.events;
CREATE TRIGGER trg_prevent_direct_event_publication_update
BEFORE UPDATE ON public.events
FOR EACH ROW
EXECUTE FUNCTION public.prevent_direct_event_publication_update();

CREATE OR REPLACE FUNCTION public.set_event_publication(
  p_event_id UUID,
  p_publication_status TEXT,
  p_publish_at TIMESTAMPTZ DEFAULT NULL,
  p_unpublish_at TIMESTAMPTZ DEFAULT NULL
)
RETURNS public.events
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  event_row public.events;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  IF p_publication_status NOT IN ('published', 'closed') THEN
    RAISE EXCEPTION 'invalid publication status';
  END IF;

  IF p_publish_at IS NOT NULL AND p_unpublish_at IS NOT NULL
    AND p_publish_at >= p_unpublish_at
  THEN
    RAISE EXCEPTION 'publish_at must be before unpublish_at';
  END IF;

  PERFORM set_config('app.event_publication_rpc', 'on', true);

  UPDATE public.events
  SET publication_status = p_publication_status,
      lifecycle_status = CASE
        WHEN lifecycle_status = 'draft' AND p_publication_status = 'published' THEN 'published'
        ELSE lifecycle_status
      END,
      publish_at = p_publish_at,
      unpublish_at = p_unpublish_at,
      updated_at = timezone('utc', now())
  WHERE id = p_event_id
    AND creator_id = auth.uid()
  RETURNING * INTO event_row;

  IF event_row.id IS NULL THEN
    RAISE EXCEPTION 'event not found or publication transition is not allowed';
  END IF;

  RETURN event_row;
END;
$$;

REVOKE ALL ON FUNCTION public.set_event_publication(UUID, TEXT, TIMESTAMPTZ, TIMESTAMPTZ) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_event_publication(UUID, TEXT, TIMESTAMPTZ, TIMESTAMPTZ) TO authenticated;

CREATE OR REPLACE FUNCTION public.apply_due_event_publication_schedules()
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  changed_count INTEGER;
BEGIN
  PERFORM set_config('app.event_publication_rpc', 'on', true);

  UPDATE public.events
  SET publication_status = CASE
        WHEN unpublish_at IS NOT NULL AND unpublish_at <= timezone('utc', now()) THEN 'closed'
        WHEN publish_at IS NOT NULL AND publish_at <= timezone('utc', now())
          AND lifecycle_status <> 'draft' THEN 'published'
        ELSE publication_status
      END,
      publish_at = CASE
        WHEN publish_at IS NOT NULL AND publish_at <= timezone('utc', now()) THEN NULL
        ELSE publish_at
      END,
      unpublish_at = CASE
        WHEN unpublish_at IS NOT NULL AND unpublish_at <= timezone('utc', now()) THEN NULL
        ELSE unpublish_at
      END,
      updated_at = timezone('utc', now())
  WHERE (publish_at IS NOT NULL AND publish_at <= timezone('utc', now()) AND lifecycle_status <> 'draft')
     OR (unpublish_at IS NOT NULL AND unpublish_at <= timezone('utc', now()));

  GET DIAGNOSTICS changed_count = ROW_COUNT;
  RETURN changed_count;
END;
$$;

REVOKE ALL ON FUNCTION public.apply_due_event_publication_schedules() FROM PUBLIC;

DROP POLICY IF EXISTS events_read_visibility ON public.events;
CREATE POLICY events_read_visibility ON public.events FOR SELECT TO authenticated
USING (
  creator_id = auth.uid()
  OR (
    lifecycle_status <> 'draft'
    AND publication_status = 'published'
    AND (
      (visibility_settings ->> 'type') IS NULL
      OR (visibility_settings ->> 'type') = 'public'
      OR (
        (visibility_settings ->> 'type') = 'connections_only'
        AND EXISTS (
          SELECT 1 FROM public.connections c
          WHERE c.status = 'accepted'
            AND ((c.requester_id = auth.uid() AND c.receiver_id = events.creator_id)
              OR (c.requester_id = events.creator_id AND c.receiver_id = auth.uid()))
        )
      )
    )
  )
);

CREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA extensions;
SELECT cron.unschedule('apply-due-event-publication-schedules')
WHERE EXISTS (
  SELECT 1 FROM cron.job WHERE jobname = 'apply-due-event-publication-schedules'
);
SELECT cron.schedule(
  'apply-due-event-publication-schedules',
  '* * * * *',
  $$SELECT public.apply_due_event_publication_schedules();$$
);

-- END HISTORICAL MIGRATION: 20260810000002_add_event_publication_control.sql

--
-- BEGIN HISTORICAL MIGRATION: 20260810000003_add_event_notification_subscriptions.sql
--
-- Activity notifications: subscriptions by event type or creator.
-- Existing events are intentionally not backfilled; only future publication
-- transitions create notifications.

CREATE TABLE IF NOT EXISTS public.event_notification_subscriptions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  event_type TEXT,
  creator_profile_id UUID REFERENCES public.profiles(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now()),
  CONSTRAINT event_notification_subscriptions_one_target
    CHECK ((event_type IS NOT NULL) <> (creator_profile_id IS NOT NULL)),
  CONSTRAINT event_notification_subscriptions_event_type_check
    CHECK (event_type IS NULL OR event_type IN (
      'Bondage', 'Discipline', 'Dominance / Submission', 'D/S',
      'Sadism / Masochism', 'SM', 'SP', 'Spanking', 'TK', 'Tickling',
      'K9', 'DID', 'CNC', 'DDLG', '4 love', 'ABDL',
      'Dining', 'BBQ', 'Karaoke', 'Movie', 'BoardGame', 'Travel',
      'BookClub', 'Conversation', 'SpeedDating', 'HangOut'
    )),
  CONSTRAINT event_notification_subscriptions_not_self
    CHECK (creator_profile_id IS NULL OR creator_profile_id <> profile_id)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_event_notification_subscriptions_type
  ON public.event_notification_subscriptions (profile_id, event_type)
  WHERE event_type IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_event_notification_subscriptions_creator
  ON public.event_notification_subscriptions (profile_id, creator_profile_id)
  WHERE creator_profile_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_event_notification_subscriptions_event_type
  ON public.event_notification_subscriptions (event_type, profile_id)
  WHERE event_type IS NOT NULL;

CREATE TABLE IF NOT EXISTS public.notifications (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  recipient_profile_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  notification_type TEXT NOT NULL
    CHECK (notification_type IN ('new_event')),
  event_id UUID NOT NULL REFERENCES public.events(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  read_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now()),
  UNIQUE (recipient_profile_id, notification_type, event_id)
);

CREATE INDEX IF NOT EXISTS idx_notifications_recipient_created_at
  ON public.notifications (recipient_profile_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_notifications_unread
  ON public.notifications (recipient_profile_id, created_at DESC)
  WHERE read_at IS NULL;

ALTER TABLE public.event_notification_subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS event_notification_subscriptions_select_self
  ON public.event_notification_subscriptions;
CREATE POLICY event_notification_subscriptions_select_self
  ON public.event_notification_subscriptions FOR SELECT TO authenticated
  USING (profile_id = auth.uid());

DROP POLICY IF EXISTS event_notification_subscriptions_insert_self
  ON public.event_notification_subscriptions;
CREATE POLICY event_notification_subscriptions_insert_self
  ON public.event_notification_subscriptions FOR INSERT TO authenticated
  WITH CHECK (
    (
      profile_id = auth.uid()
      AND creator_profile_id IS NULL
    ) OR (
      profile_id = auth.uid()
      AND creator_profile_id IS NOT NULL
      AND creator_profile_id <> auth.uid()
      AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = creator_profile_id)
    )
  );

DROP POLICY IF EXISTS event_notification_subscriptions_delete_self
  ON public.event_notification_subscriptions;
CREATE POLICY event_notification_subscriptions_delete_self
  ON public.event_notification_subscriptions FOR DELETE TO authenticated
  USING (profile_id = auth.uid());

DROP POLICY IF EXISTS notifications_select_recipient
  ON public.notifications;
CREATE POLICY notifications_select_recipient
  ON public.notifications FOR SELECT TO authenticated
  USING (recipient_profile_id = auth.uid());

DROP POLICY IF EXISTS notifications_update_read_at
  ON public.notifications;
CREATE POLICY notifications_update_read_at
  ON public.notifications FOR UPDATE TO authenticated
  USING (recipient_profile_id = auth.uid())
  WITH CHECK (recipient_profile_id = auth.uid());

-- Browser clients may only update the read marker, never notification content
-- or recipient ownership.
REVOKE UPDATE ON public.notifications FROM authenticated;
GRANT UPDATE (read_at) ON public.notifications TO authenticated;

CREATE OR REPLACE FUNCTION public.notify_subscribers_on_event_publication()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
BEGIN
  IF OLD.publication_status = 'published'
     OR NEW.publication_status <> 'published'
     OR (NEW.visibility_settings ->> 'type') = 'private'
  THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.notifications (
    recipient_profile_id,
    notification_type,
    event_id,
    title
  )
  SELECT DISTINCT s.profile_id, 'new_event', NEW.id, NEW.title
  FROM public.event_notification_subscriptions s
  WHERE s.profile_id <> NEW.creator_id
    AND (
      s.creator_profile_id = NEW.creator_id
      OR s.event_type = NEW.event_type
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.blocks b
      WHERE (b.blocker_id = s.profile_id AND b.blocked_id = NEW.creator_id)
         OR (b.blocker_id = NEW.creator_id AND b.blocked_id = s.profile_id)
    )
    AND (
      COALESCE(NEW.visibility_settings ->> 'type', 'public') = 'public'
      OR (
        NEW.visibility_settings ->> 'type' = 'connections_only'
        AND EXISTS (
          SELECT 1
          FROM public.connections c
          WHERE c.status = 'accepted'
            AND (
              (c.requester_id = s.profile_id AND c.receiver_id = NEW.creator_id)
              OR (c.requester_id = NEW.creator_id AND c.receiver_id = s.profile_id)
            )
        )
      )
    )
  ON CONFLICT (recipient_profile_id, notification_type, event_id) DO NOTHING;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_subscribers_on_event_publication ON public.events;
CREATE TRIGGER trg_notify_subscribers_on_event_publication
AFTER UPDATE OF publication_status ON public.events
FOR EACH ROW
WHEN (OLD.publication_status IS DISTINCT FROM NEW.publication_status)
EXECUTE FUNCTION public.notify_subscribers_on_event_publication();

-- END HISTORICAL MIGRATION: 20260810000003_add_event_notification_subscriptions.sql

